    java.log("模拟登录请求");
    cookie.removeCookie(source.key)
    res = source.getLoginInfoMap()

    use=res.get("帐号");
    pwd=res.get("密码");

    code=java.getVerificationCode("https://www.qf917.com/code.jpg?"+Math.random())

    body=`user_name=${use}&user_pass=${java.md5Encode(pwd)}&user_code=${code}`

   headers= {
