with(javaImport) {
    function aesDecrypt(encrypted, key, iv) {
        try {
            var encryptedBytes = Base64.getDecoder().decode(String(encrypted));
            var keyBytes = String(key).getBytes("UTF-8");
            var ivBytes = String(iv).getBytes("UTF-8");

            var secretKey = SecretKeySpec(keyBytes, "AES");
            var ivSpec = IvParameterSpec(ivBytes);
            var cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, secretKey, ivSpec);

            var decryptedBytes = cipher.doFinal(encryptedBytes);
            return String(decryptedBytes, "UTF-8");
        } catch (e) {
            java.log("解密失败: " + e.toString());
            return encrypted;
        }
    }
}


